import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../../../app/atlas_academy_app.dart';

class ProfileScreen extends StatefulWidget {
 final bool isAdmin;
 const ProfileScreen({super.key,this.isAdmin=false});
 @override State<ProfileScreen> createState()=>_ProfileScreenState();
}
class _ProfileScreenState extends State<ProfileScreen>{
 final _phone=TextEditingController(),_newEmail=TextEditingController(),_password=TextEditingController();
 bool _loading=true,_saving=false,_sending=false; Map<String,dynamic> _data={};
 User? get _user=>FirebaseAuth.instance.currentUser;
 @override void initState(){super.initState();_load();}
 Future<void> _load() async {
  try {final u=_user;if(u!=null){await u.reload();final current=FirebaseAuth.instance.currentUser;final snap=await FirebaseFirestore.instance.collection('users').doc(u.uid).get();_data=snap.data()??{};_phone.text=(_data['whatsappNumber']??'').toString();_newEmail.text=current?.email??u.email??'';if(current?.emailVerified==true&&_data['email']!=current?.email){await FirebaseFirestore.instance.collection('users').doc(u.uid).set({'email':current!.email,'emailVerified':true,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));_data['email']=current.email;}}}catch(_){} if(mounted)setState(()=>_loading=false);
 }
 Future<void> _savePhone() async {final v=_phone.text.trim(),d=v.replaceAll(RegExp(r'[^0-9]'),'');if(d.length<8||d.length>15){_msg('Enter a valid phone number.',true);return;}setState(()=>_saving=true);try{await FirebaseFirestore.instance.collection('users').doc(_user!.uid).update({'whatsappNumber':v,'updatedAt':FieldValue.serverTimestamp()});if(mounted)_msg('Phone number updated.',false);}catch(_){if(mounted)_msg('Unable to update phone number.',true);}finally{if(mounted)setState(()=>_saving=false);}}
 Future<void> _changeEmail() async {final u=_user,e=_newEmail.text.trim().toLowerCase();if(u==null||!RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(e)){_msg('Enter a valid email address.',true);return;}if(e==u.email){_msg('This is already your current email.',true);return;}if(_password.text.isEmpty){_msg('Enter your current password to confirm this change.',true);return;}setState(()=>_sending=true);try{await u.reauthenticateWithCredential(EmailAuthProvider.credential(email:u.email!,password:_password.text));await u.verifyBeforeUpdateEmail(e);if(mounted){_password.clear();_msg('Verification link sent to $e. Your email changes only after verification.',false);}}on FirebaseAuthException catch(x){if(mounted)_msg(x.code=='wrong-password'||x.code=='invalid-credential'?'The current password is incorrect.':(x.message??'Unable to request email change.'),true);}catch(_){if(mounted)_msg('Unable to request email change. Please try again.',true);}finally{if(mounted)setState(()=>_sending=false);}}
 void _msg(String s,bool error)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s),backgroundColor:error?AtlasColors.error:AtlasColors.success));
 @override void dispose(){_phone.dispose();_newEmail.dispose();_password.dispose();super.dispose();}
 @override Widget build(BuildContext context){final u=_user;final name=(_data['fullName']??u?.displayName??(widget.isAdmin?'Administrator':'Student')).toString();final photo=(_data['profileImageUrl']??'').toString();return Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('My Profile'),backgroundColor:Colors.white,foregroundColor:AtlasColors.navy,elevation:0),body:_loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(20),children:[
 Container(padding:const EdgeInsets.all(23),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AtlasColors.navy,AtlasColors.royalBlue]),borderRadius:BorderRadius.circular(24)),child:Column(children:[CircleAvatar(radius:43,backgroundColor:Colors.white24,backgroundImage:photo.isNotEmpty?NetworkImage(photo):null,child:photo.isEmpty?Text(name.isNotEmpty?name[0].toUpperCase():'?',style:const TextStyle(color:Colors.white,fontSize:30,fontWeight:FontWeight.w900)):null),const SizedBox(height:13),Text(name,style:const TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),Text(u?.email??'',style:const TextStyle(color:Colors.white70)),const SizedBox(height:8),Text(widget.isAdmin?'ADMINISTRATOR ACCOUNT':'STUDENT ACCOUNT',style:const TextStyle(color:AtlasColors.champagne,fontSize:10,letterSpacing:1.3,fontWeight:FontWeight.w900))])),
 const SizedBox(height:22),_heading('Personal Information'),_detail('Full Name',name),_detail('Father Name',_data['fatherName']),_detail('National ID / Passport',_data['nationalId']),_detail('Country of Study',_data['countryOfStudy']),_detail('University',_data['university']),_detail('Account Email',u?.email),_detail('Email Verification',u?.emailVerified==true?'Verified':'Not verified'),_detail('WhatsApp / Phone',_data['whatsappNumber']),
 if(!widget.isAdmin)...[const SizedBox(height:15),_heading('Update Phone Number'),TextField(controller:_phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'WhatsApp / Phone Number',prefixIcon:Icon(Icons.phone_rounded))),const SizedBox(height:10),SizedBox(height:49,child:FilledButton(onPressed:_saving?null:_savePhone,child:Text(_saving?'Saving…':'Save Phone Number')))],
 const SizedBox(height:24),_heading('Change Email Address'),const Text('Confirm your current password. A verification link will be sent to your new email. The account email changes only after verification.',style:TextStyle(color:AtlasColors.secondaryText,height:1.5,fontSize:12)),const SizedBox(height:12),TextField(controller:_newEmail,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'New Email Address',prefixIcon:Icon(Icons.email_outlined))),const SizedBox(height:12),TextField(controller:_password,obscureText:true,decoration:const InputDecoration(labelText:'Current Password',prefixIcon:Icon(Icons.lock_outline_rounded))),const SizedBox(height:12),SizedBox(height:50,child:OutlinedButton.icon(onPressed:_sending?null:_changeEmail,icon:const Icon(Icons.mark_email_unread_outlined),label:Text(_sending?'Sending verification…':'Verify New Email Address'))),
 if(!widget.isAdmin)...[const SizedBox(height:20),_heading('Membership'),_detail('Subscription Status',_data['subscriptionStatus']),_detail('Subscription Plan',_data['subscriptionPlanName']),_detail('Account Access',_data['accessEnabled']==true?'Enabled':'Restricted until subscription activation')]
])));}
 Widget _heading(String s)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Text(s,style:const TextStyle(color:AtlasColors.navy,fontSize:17,fontWeight:FontWeight.w900)));
 Widget _detail(String l,d)=>Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.symmetric(horizontal:15,vertical:13),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:AtlasColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(l,style:const TextStyle(color:AtlasColors.secondaryText,fontSize:11)),const SizedBox(height:4),Text(d?.toString().isNotEmpty==true?d.toString():'Not provided',style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w700))]));
}